package packet;
import java.util.ArrayList;import java.util.List;
public final class PacketInspector{
 public List<PacketMetadata> inspectPcap(byte[] data){List<PacketMetadata> out=new ArrayList<>();PcapFile file=new PcapParser().parse(data).orNull();if(file==null)return out;for(PcapRecord r:file.records()){PacketMetadata md=inspectFrame(r.data());md.timestamp(r.timestamp());md.capturedLength(r.capturedLength());md.originalLength(r.originalLength());out.add(md);}return out;}
 public PacketMetadata inspectFrame(byte[] frame){PacketMetadata md=new PacketMetadata();EthernetFrame e=EthernetFrame.parse(frame).orNull();if(e==null){md.note("not ethernet");return md;}md.linkType("ethernet");if(e.etherType()!=0x0800){md.note("ethertype 0x"+Integer.toHexString(e.etherType()));return md;}Ipv4Packet ip=Ipv4Packet.parse(e.payload()).orNull();if(ip==null){md.note("invalid ipv4");return md;}md.sourceIp(ip.source());md.destinationIp(ip.destination());md.protocol(ip.protocolName());if(ip.protocol()==6){TcpSegment tcp=TcpSegment.parse(ip.payload()).orNull();if(tcp!=null){md.sourcePort(tcp.sourcePort());md.destinationPort(tcp.destinationPort());md.note("tcp flags "+tcp.flagNames());}}else if(ip.protocol()==17){UdpDatagram udp=UdpDatagram.parse(ip.payload()).orNull();if(udp!=null){md.sourcePort(udp.sourcePort());md.destinationPort(udp.destinationPort());if(udp.sourcePort()==53||udp.destinationPort()==53){DnsMessage dns=DnsMessage.parse(udp.payload()).orNull();if(dns!=null){for(DnsQuestion q:dns.questions())md.addDnsName(q.name());for(DnsRecord r:dns.answers())md.addDnsName(r.name());}}}}return md;}
}
